def comb_sort(lst):
    def get_gap(gap):
        while gap > 1:
            gap = int(gap / 1.3)
            yield gap

    length = len(lst)
    gap = length
    swapped = True

    for gap in get_gap(gap):
        if not gap:
            break
        swapped = False
        for i in range(length - gap):
            if lst[i] > lst[i + gap]:
                lst[i], lst[i + gap] = lst[i + gap], lst[i]
                swapped = True
        if not swapped:
            break
```

