def max_diff_zeros_ones(binary_str):
    max_diff = 0
    current_diff = 0
    zero_count, one_count = binary_str.count('0'), binary_str.count('1')

    if zero_count > one_count:
        max_diff = zero_count - one_count
        current_diff = zero_count - one_count
    elif one_count > zero_count:
        max_diff = one_count - zero_count
        current_diff = one_count - zero_count

    for i in range(len(binary_str)):
        if binary_str[i] == '0':
            zero_count -= 1
            current_diff -= 2
        else:
