def find_x_y(a, b, n):
    from math import gcd

    if n < 0 or a == 0 and b == 0:
        return None

    if a == 0:
        if n % b == 0:
            return 0, n // b
        else:
            return None

    if b == 0:
        if n % a == 0:
            return n // a, 0
        else:
            return None

    d = gcd(a, b)
    if n % d != 0:
        return None

    lcm = a * b // d
    x = (n // a - b // d * (n // d)) * b // (a * b // d)
    y = (n // b - a // d * (n // d)) * a // (a * b // d)

    return x, y
```

