def largest_divisible_subset(nums):
    if not nums:
        return []
    nums.sort()
    n = len(nums)
    dp = [[] for _ in range(n)]
    dp[0] = [nums[0]]
    for i in range(1, n):
        dp[i] = [nums[i]]
        for j in range(i):
            if nums[i] % nums[j] == 0 and len(dp[j]) + 1 > len(dp[i]):
                dp[i] = dp[j] + [nums[i]]
    return max(dp, key=len)
