def min_elements_to_remove(arr, k):
    from sortedcontainers import SortedList

    sl = SortedList()
    min_diff = float('inf')
    result = float('inf')

    for num in arr:
        sl.add(num)
        for x in sl:
            if x - num <= k:
                min_diff = min(min_diff, x - num)
                if min_diff <= k:
                    result = min(result, len(sl) - sl.bisect_left(num) - (min_diff == k))
                break

    return result if min_diff <= k else -1
```

