def is_min_heap(arr, i=0, heap_size=None):
    if heap_size is None:
        heap_size = len(arr)
    if i >= heap_size:
        return True
    left = 2 * i + 1
    right = 2 * i + 2
    if left < heap_size and arr[i] > arr[left]:
        return False
    if right < heap_size and arr[i] > arr[right]:
        return False
    return is_min_heap(arr, left, heap_size) and is_min_heap(arr, right, heap_size)
```

