```python
def rgb_to_hsv(r, g, b):
    r, g, b = r / 255.0, g / 255.0, b / 255.0
    max_c = max(r, g, b)
    min_c = min(r, g, b)
    diff = max_c - min_c

    if max_c == min_c:
        hue = 0
    elif max_c == r:
        hue = (60 * ((g - b) / diff) + 360) % 360
    elif max_c == g:
        hue = (60 * ((b - r) / diff) + 120) % 360
    elif max_c == b:
        hue = (60 * ((r - g) / diff) + 240) % 360

    if max_c == 0:
        saturation = 0
    else:
        saturation = (diff / max_c) * 100

    value = max_c * 100

    return (hue, saturation, value)
```

