def generate_spiral_matrix(n):
    matrix = [[0] * n for _ in range(n)]
    dx, dy = [0, 1, 0, -1], [1, 0, -1, 0]  # right, down, left, up
    x, y, c = 0, -1, 1
    for _ in range(n // 2):
        for i in range(4):
            for _ in range((n + 1) // 2):
                x, y = x + dx[i], y + dy[i]
                matrix[x][y] = c ** 2
                c += 1
    if n % 2 == 1:
        matrix[n // 2][n // 2] = n ** 2
    return matrix
```

