def sum_of_odd_factors(n):
    if n % 2 == 0:
        n //= 2
    result = 1
    # Check for one contribution
    if n % 2 == 1:
        result *= n
    # Check for all other factors
    for i in range(3, int(n**0.5) + 1, 2):
        count = 0
        while n % i == 0:
            n //= i
            count += 1
        result *= (i**(count + 1) - 1) // (i - 1)
    if n > 2:
        result *= (n**2 - 1) // (n - 1)
    return result
```

