        return True
    for s in subset:
        if not any(isinstance(i, list) for i in s):
            if s not in superset:
                return False
        else:
            found = False
            for sup in superset:
                if isinstance(s, list) and is_nested_subset(s, sup):
                    found = True
                    break
            if not found:
                return False
    return True
