def delannoy_number(n):
    if n == 0:
        return 1
    dp = [1] * (n + 1)
    for i in range(1, n + 1):
        new_dp = [0] * (n + 1)
        for j in range(i + 1):
            if j == 0 or j == i:
                new_dp[j] = dp[j]
            else:
                new_dp[j] = dp[j] + dp[j - 1] + new_dp[j - 1]
        dp = new_dp[:]
    return dp[n]
```

