def max_segments(n, a, b, c):
    def helper(n, lengths, memo):
        if n < 0:
            return -float('inf')
        if n == 0:
            return 0
        if n in memo:
            return memo[n]
        max_segments = float('-inf')
        for length in lengths:
            max_segments = max(max_segments, 1 + helper(n - length, lengths, memo))
        memo[n] = max_segments
        return max_segments

    return helper(n, [a, b, c], {})
