def min_coins(value, coins):
    # Initialize the dp array where dp[i] will be storing the minimum number of coins
    # needed to make change for i value
    dp = [float('inf')] * (value + 1)
    dp[0] = 0  # Base case: 0 coins needed to make 0 value

    # Build the dp array
    for i in range(1, value + 1):
        for coin in coins:
            if i - coin >= 0:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    return dp[value] if dp[value] != float('inf') else -1
