def find_kth_element(arr1, arr2, k):
    def find_kth_util(arr1, arr2, k):
        if not arr1:
            return arr2[k]
        if not arr2:
            return arr1[k]
        mid1, mid2 = len(arr1) // 2, len(arr2) // 2
        mid1_val, mid2_val = arr1[mid1], arr2[mid2]

        # When k is bigger than the sum of a and b's mid index
        if k > mid1 + mid2:
            if mid1_val > mid2_val:
                return find_kth_util(arr1, arr2[mid2 + 1:], k - mid2 - 1)
            else:
                return find_kth_util(arr1[mid1 + 1:], arr2, k - mid1 - 1)
        # When k is smaller than the sum of a and b's mid index
        else:
            if mid1_val > mid2_val:
                return find_kth_util(arr1[:mid1], arr2, k)
            else:
                return find_kth_util(arr1, arr2[:mid2], k)

    return find_kth_util(arr1, arr2, k - 1)
```

